/* ===== classroom observations ===== */
TA_ACT.tacObsForm = () => {
  if (!taCan('Verify')) return; const { bid } = acBidSel(), T = acTeachers(bid).sort((a, b) => a.name.localeCompare(b.name)), me = taMe(); const cls = AC_CLASS_ORDER ? AC_CLASS_ORDER.slice() : [];
  modal('Record classroom observation', `<div class="form-grid">${pcFld('Teacher', `<select id="ob_e">${T.filter(e => !me || e.id !== me.id).map(e => `<option value="${e.id}">${esc(e.name)} (${esc(e.subject || '')})</option>`).join('')}</select>`)}${pcFld('Date', `<input id="ob_d" type="date" min="${TA_AY_FROM}" max="${PROC_TODAY}" value="${PROC_TODAY}">`)}${pcFld('Class', `<input id="ob_c" placeholder="e.g. 7 A">`)}${pcFld('Subject', '<input id="ob_s">')}</div><h4>Score each area (1 = needs support, 4 = excellent)</h4><div class="form-grid">${TA_RUBRIC.map((r, i) => pcFld(r, `<select id="ob_r${i}"><option value="">Choose</option>${[1, 2, 3, 4].map(n => `<option>${n}</option>`).join('')}</select>`)).join('')}</div>${pcFld('Strengths (at least 10 characters)', '<textarea id="ob_st" rows="2"></textarea>')}${pcFld('Areas to improve (at least 10 characters)', '<textarea id="ob_im" rows="2"></textarea>')}${pcFld('Action plan (at least 10 characters)', '<textarea id="ob_pl" rows="2"></textarea>')}<div class="form-grid">${pcFld('Follow-up date', `<input id="ob_fu" type="date" min="${PROC_TODAY}">`)}${pcFld('Recommended course (optional)', pcSel('ob_f', taD().crs.filter(c => c.state === 'Published').map(c => [c.id, c.title]), '', 'None'))}</div>`, `<button class="btn primary" data-act="tacObsOk">Submit</button><button class="btn" data-act="closeModal">Cancel</button>`, true);
};
TA_ACT.tacObsOk = async () => {
  if (!taCan('Verify')) return; const { bid } = acBidSel(), D = taD(), me = taMe(), emp = hrEmps().find(e => e.id === v('ob_e')); if (!emp || emp.bid !== bid || !taIsTeach(emp)) return toast('Choose a teacher of this branch.', 'bad'); if (me && me.id === emp.id) return toast('You cannot observe yourself.', 'bad');
  const date = v('ob_d'), cls = (v('ob_c') || '').trim(), sub = (v('ob_s') || '').trim(); if (!date || date > PROC_TODAY) return toast('The observation date cannot be in the future.', 'bad'); if (date < TA_AY_FROM) return toast('The date is before this academic year.', 'bad'); if (!cls || !sub) return toast('Enter the class and the subject.', 'bad');
  const sc = TA_RUBRIC.map((r, i) => +v('ob_r' + i)); if (sc.some(x => !(x >= 1 && x <= 4))) return toast('Score every area from 1 to 4.', 'bad'); const st = (v('ob_st') || '').trim(), im = (v('ob_im') || '').trim(); if (st.length < 10 || im.length < 10) return toast('Write the strengths and the areas to improve (at least 10 characters each).', 'bad'); const plan = (v('ob_pl') || '').trim(), fu = v('ob_fu') || ''; if (plan.length < 10) return toast('Write the action plan (at least 10 characters).', 'bad'); if (!fu || fu < PROC_TODAY) return toast('Choose a follow-up date from today onwards.', 'bad');
  if (D.obs.some(o => o.emp === emp.id && o.date === date && o.cls.toLowerCase() === cls.toLowerCase() && o.subject.toLowerCase() === sub.toLowerCase())) return toast('This observation is already recorded.', 'bad');
  const d = Store.clone(D), fc = d.crs.find(c => c.id === v('ob_f') && c.state === 'Published'); let fol = '';
  if (fc) { fol = fc.title; if (!taActiveEnr(d, fc.id, emp.id) && taFits(fc.aud, emp)) d.enr.push(taMakeEnr(d, fc, emp, App.user.name)); }
  const o = { id: 'OB' + Date.now().toString(36), bid, emp: emp.id, byEmp: me ? me.id : '', by: App.user.name, date, cls, subject: sub, scores: sc, avg: sc.reduce((a, b) => a + b, 0) / sc.length, strengths: st, improve: im, plan, followUp: fu, follow: fol, state: 'Submitted', at: nowIso() }; d.obs.push(o);
  taLog(d, `Observation recorded: ${emp.name}`, { new: `${o.avg.toFixed(2)} / 4${fol ? ', course ' + fol : ''}` }, '', bid); await taSave(d); closeModal(); toast('Observation recorded. The teacher can now respond.', 'ok');
};
TA_ACT.tacObsView = t => { const D = taD(), o = D.obs.find(x => x.id === t.dataset.k); if (!o || !taSee(o, D)) return; modal(`Observation · ${esc(acEmpName(o.emp))} · ${o.date}`, `<p class="small">${esc(o.cls)} · ${esc(o.subject)} · observed by ${esc(o.by)} · average ${o.avg.toFixed(2)} / 4</p>${table('taOR', [{ h: 'Area', k: x => x.a, t: 'text' }, { h: 'Score', k: x => x.s, t: 'num' }], taObsAreas(o).map((a, i) => ({ a, s: o.scores[i] })), { limit: 10 })}<h4>Strengths</h4><p>${esc(o.strengths)}</p><h4>Areas to improve</h4><p>${esc(o.improve)}</p>${o.plan ? `<h4>Action plan</h4><p>${esc(o.plan)}</p><p><b>Follow-up date:</b> ${esc(o.followUp || '')}${o.followUp && o.followUp < PROC_TODAY ? ' <span class="pill r">overdue</span>' : ''}</p>` : ''}${o.follow ? `<p><b>Recommended course:</b> ${esc(o.follow)}</p>` : ''}${o.resp ? `<h4>Teacher response: ${esc(o.resp.stance)}</h4><p>${esc(o.resp.comment || '—')}</p>` : '<p class="muted">The teacher has not responded yet.</p>'}`, '<button class="btn" data-act="closeModal">Close</button>', true); };
TA_ACT.tacObsAck = t => { const o = taD().obs.find(x => x.id === t.dataset.k), me = taMe(); if (!o || !me || o.emp !== me.id || o.state !== 'Submitted') return; modal('Respond to the observation', `<p class="small">${o.date} · ${esc(o.cls)} · ${esc(o.subject)} · average ${o.avg.toFixed(2)} / 4</p>${pcFld('Your response', pcSel('oa_s', ['Agree', 'Disagree'], 'Agree'))}${pcFld('Comment (required if you disagree, at least 10 characters)', '<textarea id="oa_c" rows="3"></textarea>')}`, `<button class="btn primary" data-act="tacObsAckOk" data-k="${o.id}">Submit response</button><button class="btn" data-act="closeModal">Cancel</button>`); };
TA_ACT.tacObsAckOk = async t => { const D = taD(), o = D.obs.find(x => x.id === t.dataset.k), me = taMe(); if (!o || !me || o.emp !== me.id || o.state !== 'Submitted') return; const stance = v('oa_s'), cm = (v('oa_c') || '').trim(); if (stance === 'Disagree' && cm.length < 10) return toast('Say why you disagree (at least 10 characters).', 'bad'); const d = Store.clone(D), x = d.obs.find(y => y.id === o.id); x.state = 'Responded'; x.resp = { stance, comment: cm, at: nowIso() }; taLog(d, `Observation ${stance === 'Agree' ? 'agreed' : 'disputed'} by teacher`, { new: o.date }, cm, o.bid); await taSave(d); closeModal(); toast('Response recorded.', 'ok'); };
